def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v not in (0,1)]
    if not pts:return out
    color=grid[pts[0][0]][pts[0][1]]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    # Repeat marker pattern in a regular grid, offset by motif dimensions.
    shape={(r-r0,c-c0) for r,c in pts}
    for dr in range(-h,h, r1-r0+1):
        for dc in range(-w,w, c1-c0+1):
            for a,b in shape:
                rr=r0+dr+a; cc=c0+dc+b
                if 0<=rr<h and 0<=cc<w and grid[rr][cc] in (0,1):
                    out[rr][cc]=color
    return out
